<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">token_env = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BUPHA_GHA_RUNNER_TOKEN&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # registration token env NAME (settings UI / config.sh token)</span></span>
